    $pdoLayout=\App\Core\Database::pdo();
    $stLayout=$pdoLayout->prepare('SELECT * FROM workspaces WHERE id=?'); $stLayout->execute([Auth::workspaceId()]); $workspaceLayout=$stLayout->fetch()?:null;
    $stTrial=$pdoLayout->prepare('SELECT status,trial_ends_at FROM subscriptions WHERE workspace_id=?'); $stTrial->execute([Auth::workspaceId()]); $trialLayout=$stTrial->fetch()?:null;
    if(($trialLayout['status']??'')==='trial' && !empty($trialLayout['trial_ends_at'])){ $diff=strtotime($trialLayout['trial_ends_at'])-time(); $trialDaysLeft=$diff>=0?(int)ceil($diff/86400):null; }
}
$companyLogoUrl=null; if(!empty($workspaceLayout['logo_path'])){ $logoToken=hash_hmac('sha256',(string)Auth::workspaceId(),(string)\App\Core\Env::get('APP_KEY','')); $companyLogoUrl='/mail/logo/'.(int)Auth::workspaceId().'?token='.$logoToken; }
